def find_people(n):
    grid = [[0 for _ in range(2001)] for _ in range(2001)]

    for i in range(n):
        x1, y1, x2, y2 = map(int, input().split())
        for x in range(min(x1, x2), max(x1, x2) + 1):
            for y in range(min(y1, y2), max(y1, y2) + 1):
                grid[x][y] += 1

    result = []
    for i in range(2001):
        for j in range(2001):
            if grid[i][j] > 0:
                result.append((i - 1000, j - 1000))

    return result

n = int(input())
print(n)
for people in find_people(n):
    print(*people)
